  ,SORT_ODRG
  ,PARAM_NM
  ,DATA_TYPE_CD
  ,PARAM_DESC
  ,PARAM_LOC
  ,REQUIRED
  ,PRNTS_PARAM_NO
  ,OBJ_NO
  ,OBJ_ODRG
  ,EXAM
  ,PERSONAL_DATA
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
)
VALUES
(
   #{apiNo}::integer
  ,#{paramTypeCd}
  ,#{sortOdrg}::integer
  ,#{paramNm}
  ,#{dataTypeCd}
  ,#{paramDesc}
  ,#{paramLoc}
  ,#{required}
  ,NULLIF(#{prntsParamNo}, '')::integer
  ,NULLIF(#{objNo}, '')::integer
  ,NULLIF(#{objOdrg}, '')::integer
  ,#{exam}
  ,#{personalData}
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{regr}
)
